function shouldHidePanelOnNewGameStart(panelId) {
  if (!panelId) return false;
  if (panelId === 'ability-bar') return false;
  if (panelId === 'topbar' || panelId === 'toolbar' || panelId === 'top-menubar') return false;
  return NEW_GAME_HIDDEN_PANEL_IDS.has(panelId);
}

function enforceAbilityBarHorizontal() {
  try {
    const bar = document.getElementById('ability-bar');
    if (!bar) return;
    bar.style.display = 'flex';
    bar.style.flexDirection = 'row';
    bar.style.flexWrap = 'nowrap';
    bar.style.alignItems = 'center';
    bar.style.justifyContent = 'center';
    bar.style.gap = '10px';
    bar.style.width = 'auto';
  } catch (e) {}
}

function applyNewGamePanelsHiddenDefaults() {
  try {
    if (!window._hidePanelsOnNewGameStart) return;
    NEW_GAME_HIDDEN_PANEL_IDS.forEach(id => {
      const el = document.getElementById(id);
      if (!el) return;
      if (id === 'char-card') {
        try { el.classList.add('hidden'); } catch (e) {}
      }
      el.style.display = 'none';
    });
    // Hide topbar and toolbar during intro cinematics
    try {
      const topbar = document.getElementById('topbar');
      if (topbar) topbar.style.display = 'none';
    } catch (e) {}
    try {
      const toolbar = document.getElementById('toolbar');
      if (toolbar) toolbar.style.display = 'none';
    } catch (e) {}
    try {
      const questHud = document.getElementById('quest-hud');
      if (questHud) questHud.style.display = 'none';
    } catch (e) {}
    try {
      const instructBox = document.getElementById('instruction-box');
      if (instructBox) instructBox.style.display = 'none';
    } catch (e) {}
    enforceAbilityBarHorizontal();
    try { saveAppStateDebounced(450); } catch (e) {}
  } catch (e) {}
}

function registerPanel(el) {
  if (!el) return;
  if (!el.id) el.id = 'panel-' + Math.random().toString(36).slice(2,8);
  window.FLOATING_PANELS[el.id] = el;
  // ensure panel uses the same cursor as the document/body (custom pixel cursor)
  try {
    const cssCursor = document.body && document.body.style && document.body.style.cursor;
    if (cssCursor) {
      el.style.cursor = cssCursor;
      try {
        // also propagate to common floating panel child containers so background areas match
        const inner = el.querySelectorAll('.floating-body, .meso-menu, .floating-content');
        for (const c of inner) { try { c.style.cursor = cssCursor; } catch (ee) {} }
      } catch (ee) {}
    }
  } catch (e) {}
  // restore panel position/visibility if we loaded a saved state earlier
  try {
    // prefer session-specific panel state (transient) if present
    let saved = null;
    try {
      const sess = sessionStorage.getItem('meso.panelsSession');
      if (sess) {
        const sObj = JSON.parse(sess);
        if (sObj && sObj[el.id]) saved = sObj[el.id];
      }
    } catch (e) { /* ignore session parse errors */ }
    if (!saved) saved = window._MESO_SAVED_STATE && window._MESO_SAVED_STATE.panels && window._MESO_SAVED_STATE.panels[el.id];
    if (saved) {
      if (saved.left) el.style.left = saved.left;
      if (saved.top) el.style.top = saved.top;
      if (saved.right) el.style.right = saved.right;
      if (saved.bottom) el.style.bottom = saved.bottom;
      if (saved.width) el.style.width = saved.width;
      if (saved.height) el.style.height = saved.height;
      if (saved.transform) el.style.transform = saved.transform;
      if (saved.display === 'none') el.style.display = 'none';
      if (saved.dragMoved) el.dataset.dragMoved = '1';
      // if minimized, hide body when body exists
      const body = el.querySelector && el.querySelector('.floating-body');
      if (body) {
        body.style.display = saved.minimized ? 'none' : '';
        const minBtn = el.querySelector('.btn-minimize');
        if (minBtn) minBtn.textContent = saved.minimized ? '+' : '—';
      }
    } else if (window._hidePanelsOnNewGameStart && shouldHidePanelOnNewGameStart(el.id)) {
      if (el.id === 'char-card') {
        try { el.classList.add('hidden'); } catch (e) {}
      }
      el.style.display = 'none';
    }
  } catch (e) { /* ignore */ }
}

function restoreRegisteredPanelsFromState(savedPanels) {
  try {
    if (!savedPanels || typeof savedPanels !== 'object') return;
    Object.keys(window.FLOATING_PANELS || {}).forEach(id => {
      const el = window.FLOATING_PANELS[id];
      const saved = savedPanels[id];
      if (!el || !saved) return;
      if (saved.left) el.style.left = saved.left;
      if (saved.top) el.style.top = saved.top;
      if (saved.right) el.style.right = saved.right;
      if (saved.bottom) el.style.bottom = saved.bottom;
      if (saved.width) el.style.width = saved.width;
      if (saved.height) el.style.height = saved.height;
      if (saved.transform) el.style.transform = saved.transform;
      el.style.display = saved.display === 'none' ? 'none' : '';
      if (saved.dragMoved) el.dataset.dragMoved = '1';
      const body = el.querySelector && el.querySelector('.floating-body');
      if (body) body.style.display = saved.minimized ? 'none' : '';
      const minBtn = el.querySelector && el.querySelector('.btn-minimize');
      if (minBtn) minBtn.textContent = saved.minimized ? '+' : '—';
    });
  } catch (e) {}
}
