// Async chunked terrain cache builder – yields every BATCH rows so the main
// thread stays responsive. Builds BOTH ortho and iso caches in one call.
// Categoría gruesa de un bioma, para las transiciones de borde (arena↔hierba,
// agua↔tierra…). Los caminos y canales quedan aparte porque ya tienen bordillo.
function biomeEdgeKind(b) {
  if (!b) return 'none';
  if (b === 'water' || b === 'deep_water') return 'water';
  if (b === 'grass' || b === 'riparian') return 'grass';
  if (b === 'forest') return 'forest';
  if (b === 'marsh') return 'marsh';
  if (b === 'hills') return 'hills';
  if (b === 'road' || b === 'concrete_road' || b === 'canal_road') return 'road';
  return 'sand';   // sand, steppe, alluvial, saline…
}

function biomeEdgeNeighbours(r, c) {
  const at = (rr, cc) => biomeEdgeKind(tileBiome[rr] && tileBiome[rr][cc]);
  return {
    n: at(r - 1, c), e: at(r, c + 1), s: at(r + 1, c), w: at(r, c - 1),
    nw: at(r - 1, c - 1), ne: at(r - 1, c + 1), sw: at(r + 1, c - 1), se: at(r + 1, c + 1)
  };
}

// Pinta UNA celda de terreno en un lienzo de caché (ortográfico o isométrico).
// Es el cuerpo único que comparten la reconstrucción completa
// (`rebuildMapCachesAsync`) y el repintado por regiones del mundo que crece
// (`repaintTerrainRegion`): así el terreno nuevo se pinta sin rehacer el mapa
// entero, que era lo que hacía perder fotogramas al acercarse a un borde.
// ¿Esta celda es agua? UNA sola verdad: el bioma O el mapa de rios. El minimapa
// lee `_RIVER_FULL_MAP` y el mundo solo miraba el bioma; cuando los dos no
// coincidian (partidas viejas, bandas nuevas, pasadas de coherencia a medias) el
// agua del mapa no salia en el mundo.
function isWaterPaintCell(c, r) {
  try {
    const b = tileBiome[r] && tileBiome[r][c];
    if (b === 'water' || b === 'deep_water') return true;
    const m = window._RIVER_FULL_MAP;
    if (m && m[r] && m[r][c] === 1 && b !== 'road' && b !== 'concrete_road' && b !== 'canal_road') return true;
    return false;
  } catch (e) { return false; }
}

// ── SUELO CON ARTE (recortes de la hoja del editor de entidades) ────────────
// El terreno se pintaba con colores planos + una capa de detalle procedural: las
// «texturas antiguas del suelo». Si en el editor de entidades se han recortado
// VISTAS para los suelos, la caché de terreno usa esa baldosa en lugar del
// relleno clásico:
//   · ortogonal → la baldosa tal cual, en el cuadro de la celda,
//   · isométrico → la misma baldosa deformada al rombo de la celda y enmascarada,
// con CUATRO VOLTEOS fijos por celda (elegidos con el ruido de la posición) para
// que el suelo no se vea como el mismo dibujo repetido.
// La búsqueda de la clave es la MISMA que la de los árboles
// (`claveDeArteDeArbol`): prefiere `_sup`/`_iso` según la vista y, si no hay la
// otra, la usa igual. Sin arte recortado NO cambia nada: se sigue pintando como
// antes.
const SUELO_POR_BIOMA = {
  alluvial: 'suelo_arena',
  sand: 'suelo_arena',
  desert: 'suelo_arena',
  saline: 'suelo_arena',
  steppe: 'suelo_tierra',
  grass: 'suelo_tierra',
  riparian: 'suelo_tierra',
  marsh: 'suelo_tierra',
  forest: 'suelo_tierra',
  hills: 'suelo_arcilla',
  canal_road: 'suelo_tierra',
  water: 'suelo_agua',
  deep_water: 'suelo_agua'
};

let _cacSueloArte = { clave: null, mapa: {} };
function claveDeSueloPara(bioma) {
  try {
    const base = SUELO_POR_BIOMA[bioma];
    if (!base) return null;
    const clave = ((viewMode === 'iso') ? '_iso' : '_sup') + '|' + _versionArteEntidades;
    if (_cacSueloArte.clave !== clave) _cacSueloArte = { clave, mapa: {} };
    // Sólo se guardan los ACIERTOS: cachear el «no hay arte» dejaba el suelo
    // procedural para siempre si los recortes se registraban después (sin subir
    // `_versionArteEntidades`). Un fallo son dos búsquedas de propiedad.
    const cacheado = _cacSueloArte.mapa[base];
    if (cacheado) return cacheado;
    const encontrada = claveDeArteDeArbol(base);
    if (encontrada) _cacSueloArte.mapa[base] = encontrada;
    return encontrada;
  } catch (e) { return null; }
}

// Variantes de una baldosa de suelo ya rasterizada al tamaño de la celda
// (`clave|ancho x alto|vista` → 4 lienzos: normal, espejo X, espejo Y y ambos).
const _sueloVariantes = new Map();
function sueloVariantes(clave, w, h, iso) {
  const k = clave + '|' + Math.round(w) + 'x' + Math.round(h) + (iso ? '|iso' : '|orto');
  const hit = _sueloVariantes.get(k);
  if (hit !== undefined) return hit;
  let out = null;
  try {
    const def = window.ENTITY_PIXEL_LIBRARY && window.ENTITY_PIXEL_LIBRARY[clave];
    const gw = (def && (def.gridW || def.grid)) || 9;
    const gh = (def && (def.gridH || def.grid)) || 9;
    const src = (def && Array.isArray(def.pixels)) ? getSpriteSourceBitmap(clave, def.pixels, gw, gh) : null;
    if (src && src.cv && src.w > 0 && src.h > 0) {
      const ancho = Math.max(1, Math.round(w));
      const alto = Math.max(1, Math.round(h));
      out = [];
      for (let i = 0; i < 4; i++) {
        const cv = document.createElement('canvas');
        cv.width = ancho; cv.height = alto;
        const g2 = cv.getContext('2d');
        g2.imageSmoothingEnabled = false;   // pixel-art ampliado: nítido y barato
        if (iso) {
          // Recorte al rombo de la celda (si no, las esquinas del cuadro se
          // saldrían del suelo y taparían al vecino).
          g2.beginPath();
          g2.moveTo(ancho / 2, 0);
          g2.lineTo(ancho, alto / 2);
          g2.lineTo(ancho / 2, alto);
          g2.lineTo(0, alto / 2);
          g2.closePath();
          g2.clip();
        }
        g2.translate((i & 1) ? ancho : 0, (i & 2) ? alto : 0);
        g2.scale((i & 1) ? -1 : 1, (i & 2) ? -1 : 1);
        g2.drawImage(src.cv, 0, 0, src.w, src.h, 0, 0, ancho, alto);
        out.push(cv);
      }
    }
  } catch (e) { out = null; }
  // Desalojo del más antiguo (Map conserva el orden de inserción).
  while (_sueloVariantes.size > 60) {
    const primero = _sueloVariantes.keys().next();
    if (primero.done) break;
    _sueloVariantes.delete(primero.value);
  }
  _sueloVariantes.set(k, out);
  return out;
}

// Pinta la baldosa de suelo en la caché. `px`,`py` son el cuadro de la celda
// (ortogonal) o el VÉRTICE SUPERIOR del rombo (isométrico).
function pintarSueloConArte(g, clave, px, py, w, h, iso, seed) {
  const vars = sueloVariantes(clave, w, h, iso);
  if (!vars) return false;
  const cv = vars[(seed >>> 3) & 3] || vars[0];
  const previo = g.imageSmoothingEnabled;
  g.imageSmoothingEnabled = false;
  if (iso) g.drawImage(cv, Math.round(px - w / 2), Math.round(py));
  else g.drawImage(cv, Math.round(px), Math.round(py));
  g.imageSmoothingEnabled = previo;
  return true;
}

function paintTerrainCellInCache(g, c, r, opts = {}) {
  const iso = !!opts.iso;
  const w1 = TILE, h1 = TILE * ISO_RATIO;
  const px = iso ? Math.floor((c - r) * (w1 / 2) - (opts.minX || 0))
                 : c * TILE;
  const py = iso ? Math.floor((c + r) * (h1 / 2) - h1 / 2 - (opts.minY || 0))
                 : r * TILE;
  const tw = iso ? w1 : TILE;
  const th = iso ? h1 : TILE;
  const biome = isWaterPaintCell(c, r) ? 'water' : ((tileBiome[r] && tileBiome[r][c]) || 'alluvial');
  const isUrss = (window._currentEpoch || 'mesopotamia') === 'urss';
  const noise = ((c * 7 + r * 13) % 11) * 0.8;
  const seed = (((c + 4096) * 73856093) ^ ((r + 4096) * 19349663)) >>> 0;
  // ¿Hay arte recortado para el suelo de este bioma? Entonces la baldosa SUSTITUYE
  // al relleno plano, a las transiciones entre biomas y al detalle procedural: si
  // se pintaran encima, el arte no se vería y seguiríamos mezclando los dos estilos.
  // Los CAMINOS (`road` y `concrete_road`) se dejan como están a propósito:
  // llevan empedrado por piezas, bordillos automáticos y puentes de madera, y un
  // cambio de baldosa ahí se los comería (para eso está `suelo_pavimento`, que se
  // puede recortar y conectar cuando se decida cómo combinar los bordillos).
  if (biome !== 'road' && biome !== 'concrete_road') {
    const claveSuelo = claveDeSueloPara(biome);
    if (claveSuelo && pintarSueloConArte(g, claveSuelo, px, py, tw, th, iso, seed)) {
      // El agua conserva la animación: las ondas se pintan por fotograma ENCIMA
      // de la caché (`drawWaterAnimCell`), así que la baldosa se sigue viendo.
      return;
    }
  }
  if (iso) {
    if (biome === 'road') {
      g.fillStyle = isUrss ? `rgb(${130+noise|0},${134+noise|0},${140+noise|0})` : `rgb(${210+noise|0},${180+noise|0},${130+noise|0})`;
    } else if (biome === 'concrete_road') {
      g.fillStyle = `rgb(${140+noise|0},${144+noise|0},${150+noise|0})`;
    } else {
      g.fillStyle = getBiomeFillColor(biome);
    }
    g.beginPath();
    g.moveTo(px,        py);
    g.lineTo(px + w1/2, py + h1/2);
    g.lineTo(px,        py + h1);
    g.lineTo(px - w1/2, py + h1/2);
    g.closePath(); g.fill();
  } else {
    if (biome === 'road') {
      g.fillStyle = isUrss ? `rgb(${130+noise|0},${134+noise|0},${140+noise|0})` : `rgb(${210+noise|0},${180+noise|0},${130+noise|0})`;
    } else if (biome === 'concrete_road') {
      g.fillStyle = `rgb(${140+noise|0},${144+noise|0},${150+noise|0})`;
    } else {
      g.fillStyle = getBiomeFillColor(biome);
    }
    g.fillRect(px, py, tw, th);
  }
  // La caché pintaba SÓLO colores planos, así que las texturas de camino, los
  // puentes y el detalle del bioma no se veían nunca en el juego (sólo en el
  // fotograma previo a tener caché). Se pintan aquí también.
  try {
    const texOpts = iso ? { iso: true } : {};
    // Bordes entre biomas: dither y orilla húmeda (16 bits, no bloques)
    if (biome !== 'road' && biome !== 'concrete_road') {
      const kind = biomeEdgeKind(biome);
      if (kind !== 'road') textures.drawTransition(g, px, py, th, kind, biomeEdgeNeighbours(r, c), seed, texOpts);
    }
    if (biome === 'road' || biome === 'concrete_road' || biome === 'canal_road') {
      if (biome === 'canal_road') {
        // Corredor logístico: tierra apisonada (sin textura de calzada)
      } else {
        const kind = biome === 'concrete_road' ? 'concrete' : pathKindAt(c, r);
        const axis = bridgeAxisAt(c, r);
        if (axis) {
          textures.drawBridgeCell(g, px, py, tw, th, axis, seed, 'wood', texOpts);
        } else {
          textures.drawPathTile(g, px, py, tw, th, kind, seed, texOpts);
          const closed = {
            n: !isPathCell(c, r - 1), e: !isPathCell(c + 1, r),
            s: !isPathCell(c, r + 1), w: !isPathCell(c - 1, r)
          };
          textures.drawCurbs(g, px, py, tw, th, closed, kind, texOpts);
        }
      }
    } else if (biome !== 'water') {
      textures.drawDetailTile(g, px, py, tw, th, biome, seed, texOpts);
    }
  } catch (e) {}
}

// Geometría del lienzo isométrico (rombo del mundo) para un tamaño dado.
function isoTerrainCacheGeometry(cols, rows) {
  const w1 = TILE, h1 = TILE * ISO_RATIO;
  const proj = (col, row) => ({ x: (col - row) * (w1 / 2), y: (col + row) * (h1 / 2) - h1 / 2 });
  const corners = [proj(0, 0), proj(cols - 1, 0), proj(0, rows - 1), proj(cols - 1, rows - 1)];
  const minX = Math.floor(Math.min.apply(null, corners.map(p => p.x)) - w1 / 2);
  const maxX = Math.ceil(Math.max.apply(null, corners.map(p => p.x)) + w1 / 2);
  const minY = Math.floor(Math.min.apply(null, corners.map(p => p.y)));
  const maxY = Math.ceil(Math.max.apply(null, corners.map(p => p.y)) + h1);
  return { proj, minX, minY, w: Math.max(1, maxX - minX), h: Math.max(1, maxY - minY) };
}

// Repinta SÓLO una región de celdas en las cachés de terreno que ya existan.
// Se usa al crecer el mundo (+1 celda de margen, porque las transiciones y los
// rombos del isométrico se solapan con los vecinos).
function repaintTerrainRegion(c0, r0, c1, r1) {
  try {
    const mc0 = Math.max(0, Math.floor(c0) - 1), mc1 = Math.min(COLS - 1, Math.ceil(c1) + 1);
    const mr0 = Math.max(0, Math.floor(r0) - 1), mr1 = Math.min(ROWS - 1, Math.ceil(r1) + 1);
    if (mc1 < mc0 || mr1 < mr0) return false;
    if (mapCacheOrtho && mapCacheOrtho.width === COLS * TILE && mapCacheOrtho.height === ROWS * TILE) {
      const oc = mapCacheOrtho.getContext('2d');
      for (let r = mr0; r <= mr1; r++) for (let c = mc0; c <= mc1; c++) paintTerrainCellInCache(oc, c, r, { iso: false });
    }
    if (mapCacheIso && mapCacheIso._isoOffset) {
      const geo = isoTerrainCacheGeometry(COLS, ROWS);
      const off = mapCacheIso._isoOffset;
      if (mapCacheIso.width === geo.w && mapCacheIso.height === geo.h && off.minX === geo.minX && off.minY === geo.minY) {
        const ic = mapCacheIso.getContext('2d');
        for (let r = mr0; r <= mr1; r++) for (let c = mc0; c <= mc1; c++) paintTerrainCellInCache(ic, c, r, { iso: true, minX: geo.minX, minY: geo.minY });
      } else {
        // El lienzo iso no cuadra con el tamaño nuevo: se reconstruye en segundo
        // plano (sólo si se está usando el isométrico).
        if (viewMode === 'iso') { mapCacheDirty = true; rebuildMapCacheDebounced(10); }
      }
    }
    return true;
  } catch (e) { return false; }
}

// Repintado por TROZOS de la banda nueva. El repintado detallado (texturas,
// transiciones, bordillos) cuesta decenas de ms por fila y hacerlo de golpe
// congelaba el juego; aquí se pinta primero el color plano de cada celda (una
// pasada barata, para que no quede un agujero) y luego se va añadiendo el detalle
// unas filas por fotograma.
let _bandRepaintQueue = [];
let _bandRepaintRunning = false;

function flatFillTerrainRegion(c0, r0, c1, r1) {
  const geoIso = isoTerrainCacheGeometry(COLS, ROWS);
  const fill = (g, iso, minX, minY) => {
    for (let r = r0; r <= r1; r++) {
      for (let c = c0; c <= c1; c++) {
        const biome = (tileBiome[r] && tileBiome[r][c]) || 'alluvial';
        g.fillStyle = getBiomeFillColor(biome);
        if (iso) {
          const w1 = TILE, h1 = TILE * ISO_RATIO;
          const px = Math.floor((c - r) * (w1 / 2) - minX);
          const py = Math.floor((c + r) * (h1 / 2) - h1 / 2 - minY);
          g.beginPath();
          g.moveTo(px, py); g.lineTo(px + w1 / 2, py + h1 / 2);
          g.lineTo(px, py + h1); g.lineTo(px - w1 / 2, py + h1 / 2);
          g.closePath(); g.fill();
        } else {
          g.fillRect(c * TILE, r * TILE, TILE, TILE);
        }
      }
    }
  };
  try {
    if (mapCacheOrtho && mapCacheOrtho.width === COLS * TILE && mapCacheOrtho.height === ROWS * TILE) {
      fill(mapCacheOrtho.getContext('2d'), false, 0, 0);
    }
    if (mapCacheIso && mapCacheIso._isoOffset && mapCacheIso.width === geoIso.w && mapCacheIso.height === geoIso.h) {
      fill(mapCacheIso.getContext('2d'), true, geoIso.minX, geoIso.minY);
    }
  } catch (e) {}
}

function queueTerrainBandRepaint(c0, r0, c1, r1) {
  try {
    const c0c = Math.max(0, Math.floor(c0) - 1), c1c = Math.min(COLS - 1, Math.ceil(c1) + 1);
    const r0c = Math.max(0, Math.floor(r0) - 1), r1c = Math.min(ROWS - 1, Math.ceil(r1) + 1);
    if (c1c < c0c || r1c < r0c) return false;
    flatFillTerrainRegion(c0c, r0c, c1c, r1c);
    _bandRepaintQueue.push({ c0: c0c, r0: r0c, c1: c1c, r1: r1c, r: r0c });
    if (!_bandRepaintRunning) {
      _bandRepaintRunning = true;
      setTimeout(runBandRepaintChunk, 0);
    }
    return true;
  } catch (e) { return false; }
}

function runBandRepaintChunk() {
  const ROWS_PER_TICK = 3;
  try {
    let guard = 0;
    while (guard++ < ROWS_PER_TICK && _bandRepaintQueue.length) {
      const job = _bandRepaintQueue[0];
      const r = job.r;
      if (r > job.r1) { _bandRepaintQueue.shift(); continue; }
      const geoIso = isoTerrainCacheGeometry(COLS, ROWS);
      if (mapCacheOrtho && mapCacheOrtho.width === COLS * TILE && mapCacheOrtho.height === ROWS * TILE) {
        const g = mapCacheOrtho.getContext('2d');
        for (let c = job.c0; c <= job.c1; c++) paintTerrainCellInCache(g, c, r, { iso: false });
      }
      if (mapCacheIso && mapCacheIso._isoOffset && mapCacheIso.width === geoIso.w && mapCacheIso.height === geoIso.h) {
        const g = mapCacheIso.getContext('2d');
        for (let c = job.c0; c <= job.c1; c++) paintTerrainCellInCache(g, c, r, { iso: true, minX: geoIso.minX, minY: geoIso.minY });
      }
      job.r = r + 1;
      if (job.r > job.r1) _bandRepaintQueue.shift();
    }
  } catch (e) { console.warn('repintado de banda', e); }
  if (_bandRepaintQueue.length) {
    setTimeout(runBandRepaintChunk, 0);
  } else {
    _bandRepaintRunning = false;
    mapCacheDirty = false;
  }
}

// Al CRECER el mundo las cachés se AMPLÍAN conservando lo ya pintado: se crea el
// lienzo nuevo del tamaño que toca y se pega el viejo desplazado. Antes se
// tiraban y se reconstruían enteras (las dos vistas) → tirón de rendimiento.
function growTerrainCaches(dc, dr) {
  try {
    const tileSize = TILE;
    const oW = COLS * tileSize, oH = ROWS * tileSize;
    const oldO = mapCacheOrtho;
    if (oldO && oldO.width > 1) {
      const next = document.createElement('canvas');
      next.width = Math.max(1, oW); next.height = Math.max(1, oH);
      const nc = next.getContext('2d');
      try { nc.imageSmoothingEnabled = false; } catch (e) {}
      nc.drawImage(oldO, dc * tileSize, dr * tileSize);
      mapCacheOrtho = next;
      mapCacheOrtho._cacheZoom = 1;
    }
    const geo = isoTerrainCacheGeometry(COLS, ROWS);
    const oldI = mapCacheIso;
    const oldOff = (oldI && oldI._isoOffset) ? oldI._isoOffset : null;
    if (oldI && oldOff && oldI.width > 1) {
      const next = document.createElement('canvas');
      next.width = geo.w; next.height = geo.h;
      const ic = next.getContext('2d');
      try { ic.imageSmoothingEnabled = false; } catch (e) {}
      // Dónde estaba la celda (0,0) en el lienzo viejo y dónde debe estar ahora.
      const oldOrigin = { x: geo.proj(0, 0).x - oldOff.minX, y: geo.proj(0, 0).y - oldOff.minY };
      const newOrigin = { x: geo.proj(dc, dr).x - geo.minX, y: geo.proj(dc, dr).y - geo.minY };
      ic.drawImage(oldI, Math.floor(newOrigin.x - oldOrigin.x), Math.floor(newOrigin.y - oldOrigin.y));
      mapCacheIso = next;
      mapCacheIso._isoOffset = { minX: geo.minX, minY: geo.minY };
      mapCacheIso._cacheZoom = 1;
    }
    return true;
  } catch (e) { return false; }
}

// Huella BARATA del estado del terreno: cuantas celdas son agua (mirando bioma y
// mapa de rios) y un muestreo de biomas. Sirve para detectar que la cache de
// terreno se ha quedado vieja sin tener que comparar celdas una a una.
let mapCacheFingerprint = '';
function terrainCacheFingerprint() {
  try {
    let agua = 0, hash = 0;
    const step = 3;
    for (let r = 0; r < ROWS; r += step) {
      for (let c = 0; c < COLS; c += step) {
        const b = (tileBiome[r] && tileBiome[r][c]) || '';
        const esAgua = (b === 'water' || b === 'deep_water' || (window._RIVER_FULL_MAP && window._RIVER_FULL_MAP[r] && window._RIVER_FULL_MAP[r][c] === 1));
        if (esAgua) agua++;
        hash = (hash * 31 + (b.length * 7) + (esAgua ? 101 : 0)) | 0;
      }
    }
    return agua + '|' + hash + '|' + COLS + 'x' + ROWS;
  } catch (e) { return ''; }
}

// ── Celdas ya pintadas de la caché que se está construyendo ───────────────────
// Pintar las 21.600 celdas de un mundo cuesta ~1 s en el navegador y MUCHO más en
// equipos con rasterizado por software (Electron): con el bucle «todo de golpe,
// cediendo el hilo cada 20 filas» cada turno bloqueaba el fotograma segundos y,
// mientras, el juego se quedaba en el cartel de carga. Con este registro se pinta
// PRIMERO la zona visible (el mundo aparece enseguida) y el resto por turnos de
// ~12 ms, sin repintar ninguna celda dos veces.
let _terrainPaintedMask = null;
let _terrainPaintedView = null;
let _terrainPaintedCount = 0;

function terrainPaintedStart(view) {
  try { _terrainPaintedMask = new Uint8Array(COLS * ROWS); } catch (e) { _terrainPaintedMask = null; }
  _terrainPaintedView = view;
  _terrainPaintedCount = 0;
  window._terrainPaintedMask = null;
  window._terrainPaintPct = 0;
}
function terrainPaintedEnd() {
  _terrainPaintedMask = null;
  _terrainPaintedView = null;
  _terrainPaintedCount = 0;
  window._terrainPaintedMask = null;
  window._terrainCachePartial = false;
}
function terrainCellPainted(c, r) {
  if (!_terrainPaintedMask) return false;
  if (c < 0 || r < 0 || c >= COLS || r >= ROWS) return true;
  return _terrainPaintedMask[r * COLS + c] === 1;
}
function terrainMarkPainted(c, r) {
  if (!_terrainPaintedMask || c < 0 || r < 0 || c >= COLS || r >= ROWS) return;
  const i = r * COLS + c;
  if (_terrainPaintedMask[i] === 1) return;
  _terrainPaintedMask[i] = 1;
  _terrainPaintedCount++;
}
// Progreso del pintado (celdas pintadas / total), para el cartel de carga.
function terrainUpdatePaintPct() {
  try { window._terrainPaintPct = Math.round((_terrainPaintedCount / Math.max(1, COLS * ROWS)) * 100); } catch (e) {}
}

// Rectángulo de celdas que se ve ahora mismo (con margen), válido en las dos
// vistas: se invierten las cuatro esquinas de la ventana.
function visibleTerrainCellRect(pad) {
  const p = Math.max(0, pad || 0);
  try {
    const w = canvas.width, h = canvas.height;
    const esquinas = [screenToWorld(0, 0), screenToWorld(w, 0), screenToWorld(0, h), screenToWorld(w, h)];
    let c0 = Infinity, r0 = Infinity, c1 = -Infinity, r1 = -Infinity;
    for (const q of esquinas) {
      if (!q || !Number.isFinite(q.col) || !Number.isFinite(q.row)) continue;
      c0 = Math.min(c0, q.col); c1 = Math.max(c1, q.col);
      r0 = Math.min(r0, q.row); r1 = Math.max(r1, q.row);
    }
    if (!Number.isFinite(c0)) return { c0: 0, r0: 0, c1: COLS - 1, r1: ROWS - 1 };
    return {
      c0: Math.max(0, Math.floor(c0) - p), c1: Math.min(COLS - 1, Math.ceil(c1) + p),
      r0: Math.max(0, Math.floor(r0) - p), r1: Math.min(ROWS - 1, Math.ceil(r1) + p)
    };
  } catch (e) { return { c0: 0, r0: 0, c1: COLS - 1, r1: ROWS - 1 }; }
}

// Pinta las celdas que falten de un rectángulo (con el registro de pintadas).
function paintTerrainRectInCache(g, c0, r0, c1, r1, opts) {
  let n = 0;
  for (let r = r0; r <= r1; r++) {
    for (let c = c0; c <= c1; c++) {
      if (terrainCellPainted(c, r)) continue;
      paintTerrainCellInCache(g, c, r, opts);
      terrainMarkPainted(c, r);
      n++;
    }
  }
  return n;
}

// ¿Se puede usar la caché aunque todavía se esté pintando el resto del mundo?
// Sí: la pasada 1 pinta la ZONA VISIBLE y el volcado va recortado a la ventana,
// así que lo que se enseña está pintado. Si la vista cambió a mitad de la
// construcción (la máscara es de la otra vista) no se usa.
function _terrainParcialUsable() {
  try {
    return !!window._terrainCachePartial && _terrainPaintedView === viewMode && !!_terrainPaintedMask;
  } catch (e) { return false; }
}

// Remata (pinta) la zona visible si la caché se está construyendo por partes.
function _terrainRematarZonaVisible(_mc) {
  if (!window._terrainCachePartial || !_terrainPaintedMask || _terrainPaintedView !== viewMode) return;
  const vis = visibleTerrainCellRect(3);
  let faltan = false;
  for (let r = vis.r0; r <= vis.r1 && !faltan; r++) {
    for (let c = vis.c0; c <= vis.c1; c++) {
      if (!_terrainPaintedMask[r * COLS + c]) { faltan = true; break; }
    }
  }
  if (!faltan) return;
  const g = (viewMode === 'iso') ? (mapCacheIso && mapCacheIso.getContext('2d')) : (mapCacheOrtho && mapCacheOrtho.getContext('2d'));
  if (!g) return;
  const opts = (viewMode === 'iso' && _mc && _mc._isoOffset)
    ? { iso: true, minX: _mc._isoOffset.minX, minY: _mc._isoOffset.minY }
    : { iso: false };
  paintTerrainRectInCache(g, vis.c0, vis.r0, vis.c1, vis.r1, opts);
  try { window._terrainVisRepaints = (window._terrainVisRepaints || 0) + 1; } catch (e) {}
}

async function rebuildMapCachesAsync() {
  if (_rebuildMapAsyncRunning) return;
  _rebuildMapAsyncRunning = true;
  const _tRepintado = performance.now();
  window._terrCacheBusy = true;
  window._terrCacheBusyFrom = window._terrCacheBusyFrom || Date.now();
  const PRESUPUESTO_MS = 12;   // trabajo por turno antes de ceder el hilo
  const tileSize = TILE;
  // SOLO se construye la caché de la vista ACTIVA: la otra se deja pendiente y se
  // construye al cambiar de vista (`setViewMode`).
  const quiereIso = (viewMode === 'iso');
  window._cachePendiente = quiereIso ? 'ortho' : 'iso';
  terrainPaintedStart(quiereIso ? 'iso' : 'ortho');
  try {
    let g, opts;
    if (!quiereIso) {
      // ── Pasada ortogonal ──
      const oW = COLS * tileSize, oH = ROWS * tileSize;
      if (!mapCacheOrtho || mapCacheOrtho.width !== oW || mapCacheOrtho.height !== oH) {
        mapCacheOrtho = document.createElement('canvas');
        mapCacheOrtho.width = Math.max(1, oW); mapCacheOrtho.height = Math.max(1, oH);
      }
      g = mapCacheOrtho.getContext('2d');
      g.clearRect(0, 0, oW, oH);
      opts = { iso: false };
      delete mapCacheOrtho._isoOffset;
      mapCacheOrtho._cacheZoom = 1;
      mapCacheOrtho._vista = 'ortho';
    } else {
      // ── Pasada isométrica ──
      const geoIso = isoTerrainCacheGeometry(COLS, ROWS);
      const minX1 = geoIso.minX;
      const minY1 = geoIso.minY;
      const iW = geoIso.w, iH = geoIso.h;
      if (!mapCacheIso || mapCacheIso.width !== iW || mapCacheIso.height !== iH) {
        mapCacheIso = document.createElement('canvas');
        mapCacheIso.width = Math.max(1, iW); mapCacheIso.height = Math.max(1, iH);
      }
      g = mapCacheIso.getContext('2d');
      g.clearRect(0, 0, iW, iH);
      opts = { iso: true, minX: minX1, minY: minY1 };
      mapCacheIso._isoOffset = { minX: minX1, minY: minY1 };
      mapCacheIso._cacheZoom = 1;
      mapCacheIso._vista = 'iso';
    }

    // 1) PRIMERO lo que se ve, también por turnos de ~12 ms: en cuanto termina
    //    esta pasada el volcado (recortado a la ventana) ya es correcto y el
    //    cartel de carga se retira, aunque el resto del mundo siga pintándose
    //    por detrás.
    let vis = null;
    try {
      vis = visibleTerrainCellRect(3);
      const t0 = performance.now();
      let tVis = performance.now();
      for (let rr = vis.r0; rr <= vis.r1; rr++) {
        for (let c = vis.c0; c <= vis.c1; c++) {
          if (terrainCellPainted(c, rr)) continue;
          paintTerrainCellInCache(g, c, rr, opts);
          terrainMarkPainted(c, rr);
        }
        terrainUpdatePaintPct();
        if ((performance.now() - tVis) >= PRESUPUESTO_MS) { await cederHilo(); tVis = performance.now(); }
      }
      window._terrainVisPaintedAt = Date.now();
      window._terrainVisPaintMs = Math.round(performance.now() - t0);
    } catch (e) { console.warn('caché: pasada visible', e); }
    if (!vis) vis = { c0: 0, r0: 0, c1: COLS - 1, r1: ROWS - 1 };
    window._terrainCachePartial = true;
    window._terrainPaintedMask = _terrainPaintedMask;

    // 2) El resto del mundo, por turnos de ~12 ms (cediendo el hilo entre turnos)
    //    y empezando por las filas MÁS CERCANAS a lo que se ve: si el jugador
    //    camina hacia terreno aún sin pintar, lo que tiene al lado ya está hecho.
    const centroFila = Math.max(0, Math.min(ROWS - 1, Math.round((vis.r0 + vis.r1) / 2)));
    const ordenFilas = [centroFila];
    for (let d = 1; d < ROWS && ordenFilas.length < ROWS; d++) {
      const a = centroFila - d, b = centroFila + d;
      if (a >= 0) ordenFilas.push(a);
      if (b < ROWS) ordenFilas.push(b);
    }
    let tTurno = performance.now();
    let hechas = 0;
    for (const rr of ordenFilas) {
      for (let c = 0; c < COLS; c++) {
        if (terrainCellPainted(c, rr)) continue;
        paintTerrainCellInCache(g, c, rr, opts);
        terrainMarkPainted(c, rr);
      }
      hechas++;
      terrainUpdatePaintPct();
      if ((performance.now() - tTurno) >= PRESUPUESTO_MS && hechas < ROWS) {
        await cederHilo();
        tTurno = performance.now();
      }
    }
    window._terrainPaintPct = 100;

    mapCacheDirty = false;
    // Huella del terreno que acaba de pintarse: si mas tarde cambia (crecimiento,
    // pasada de coherencia, partida cargada con otro mapa...), el vigilante de la
    // cache la marca sucia y se repinta sola.
    try { mapCacheFingerprint = terrainCacheFingerprint(); } catch (e) {}
    try { window._terrainCacheBuiltAt = Date.now(); } catch (e) {}
  } catch (e) { console.warn('rebuildMapCachesAsync err', e); }
  terrainPaintedEnd();
  _rebuildMapAsyncRunning = false;
  window._terrCacheBusy = false;
  window._terrCacheBusyFrom = 0;
  // Contadores para poder MEDIR si la caché del suelo se repinta más de la cuenta
  // (cada repintado pinta ~21.600 celdas: si sube sin parar, ahí está el tirón).
  try {
    window._terrainRebuilds = (window._terrainRebuilds || 0) + 1;
    window._terrainRebuildMs = Math.round(performance.now() - _tRepintado);
  } catch (e) {}
}

function rebuildMapCacheDebounced(delay = GRAPHICS_CONFIG.cacheRebuildDelay) {
  if (_rebuildMapTimer) clearTimeout(_rebuildMapTimer);
  // Use the async chunked builder so the main thread is never blocked.
  _rebuildMapTimer = setTimeout(() => { try { rebuildMapCachesAsync(); } catch (e) { console.warn('rebuildMapCaches err', e); } }, delay);
}

function rebuildMapCache() {
  // PERF: always build cache at BASE tile size (TILE px, zoom=1).
  // This keeps the canvas at a fixed ~22 MB regardless of zoom level.
  // The render loop scales it with drawImage(scale=zoom) which the GPU handles cheaply.
  const tileSize = TILE; // do NOT use getTileSize() — that would scale with zoom
  if (viewMode === 'iso') {
    // compute projected iso extents at BASE zoom (1)
    const w1 = TILE;
    const h1 = TILE * ISO_RATIO;
    function proj1(col, row) { return { x: (col - row) * (w1 / 2), y: (col + row) * (h1 / 2) - h1 / 2 }; }
    const a = proj1(0,0), b = proj1(COLS-1,0), c = proj1(0,ROWS-1), d = proj1(COLS-1,ROWS-1);
    const minX1 = Math.floor(Math.min(a.x,b.x,c.x,d.x) - w1 / 2);
    const maxX1 = Math.ceil(Math.max(a.x,b.x,c.x,d.x) + w1/2);
    const minY1 = Math.floor(Math.min(a.y,b.y,c.y,d.y));
    const maxY1 = Math.ceil(Math.max(a.y,b.y,c.y,d.y) + h1);
    const W = maxX1 - minX1; const H = maxY1 - minY1;
    if (!mapCache || mapCache.width !== W || mapCache.height !== H) {
      mapCache = document.createElement('canvas');
      mapCache.width = Math.max(1, W); mapCache.height = Math.max(1, H);
    }
    const cctx = mapCache.getContext('2d');
    cctx.clearRect(0,0,mapCache.width,mapCache.height);
    // draw tiles into cache
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const p = proj1(c, r);
        const x = Math.floor(p.x - minX1);
        const y = Math.floor(p.y - minY1);
        const biome = tileBiome[r][c] || 'alluvial';
        cctx.fillStyle = getBiomeFillColor(biome);
        cctx.beginPath();
        cctx.moveTo(x, y);
        cctx.lineTo(x + w1/2, y + h1/2);
        cctx.lineTo(x, y + h1);
        cctx.lineTo(x - w1/2, y + h1/2);
        cctx.closePath(); cctx.fill();
      }
    }
    mapCache._isoOffset = { minX: minX1, minY: minY1 };
    mapCache._cacheZoom = 1; // cache is always at base zoom
  } else {
    // orthographic cache at base tileSize
    const W = COLS * tileSize; const H = ROWS * tileSize;
    if (!mapCache || mapCache.width !== W || mapCache.height !== H) {
      mapCache = document.createElement('canvas');
      mapCache.width = Math.max(1, W); mapCache.height = Math.max(1, H);
    }
    const cctx = mapCache.getContext('2d');
    cctx.clearRect(0,0,mapCache.width,mapCache.height);
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const x = c * tileSize; const y = r * tileSize;
        const biome = tileBiome[r][c] || 'alluvial';
        const isUrss = (window._currentEpoch || 'mesopotamia') === 'urss';
        const noise = ((c * 7 + r * 13) % 11) * 0.8;
        if (biome === 'road') {
          cctx.fillStyle = isUrss ? `rgb(${130+noise|0},${134+noise|0},${140+noise|0})` : `rgb(${210+noise|0},${180+noise|0},${130+noise|0})`;
        } else if (biome === 'concrete_road') {
          cctx.fillStyle = `rgb(${140+noise|0},${144+noise|0},${150+noise|0})`;
        } else {
          cctx.fillStyle = getBiomeFillColor(biome);
        }
        cctx.fillRect(x, y, tileSize, tileSize);
        // canal_road texture: subtle road stripes
        if (biome === 'canal_road' && tileSize >= 6) {
          cctx.fillStyle = 'rgba(90,60,20,0.18)';
          cctx.fillRect(x, y, tileSize, Math.max(1, Math.round(tileSize * 0.12)));
          cctx.fillRect(x, y + tileSize - Math.max(1, Math.round(tileSize * 0.12)), tileSize, Math.max(1, Math.round(tileSize * 0.12)));
          // dashed centre line
          if (c % 2 === 0) { cctx.fillStyle = 'rgba(255,230,120,0.28)'; cctx.fillRect(x + Math.round(tileSize*0.42), y + Math.round(tileSize*0.44), Math.round(tileSize*0.16), Math.round(tileSize*0.12)); }
        }
        // alluvial variation: subtle grain
        if (biome === 'alluvial' && tileSize >= 8 && (r + c) % 3 === 0) {
          cctx.fillStyle = 'rgba(0,0,0,0.04)';
          cctx.fillRect(x + Math.round(tileSize*0.2), y + Math.round(tileSize*0.2), Math.round(tileSize*0.6), Math.round(tileSize*0.6));
        }
      }
    }
    delete mapCache._isoOffset;
    mapCache._cacheZoom = 1; // cache is always at base zoom
  }
  mapCacheDirty = false;
}

// Quick diagnostic overlay to verify the module loaded in-browser
try {
  const diag = document.createElement('div');
  diag.id = 'engine-status';
  diag.textContent = 'Engine: loaded';
  diag.style.position = 'fixed';
  diag.style.right = '8px';
  diag.style.top = '8px';
  diag.style.background = 'rgba(0,0,0,0.6)';
  diag.style.color = '#FFD27A';
  diag.style.padding = '6px 8px';
  diag.style.zIndex = 99999;
  diag.style.fontFamily = 'sans-serif';
  diag.style.fontSize = '12px';
  document.body.appendChild(diag);
} catch (err) { console.error('Could not create diag overlay', err); }

// Global error handlers to surface runtime errors visibly
window.addEventListener('error', function (e) {
  console.error('Unhandled error', e.error || e.message || e);
  try {
    const el = document.getElementById('fatal-error-overlay') || document.createElement('div');
    el.id = 'fatal-error-overlay';
    el.style.position = 'fixed'; el.style.left = '8px'; el.style.top = '8px'; el.style.right = '8px';
    el.style.padding = '10px'; el.style.background = 'rgba(40,0,0,0.9)'; el.style.color = '#fff'; el.style.zIndex = 9999;
    el.style.fontFamily = 'monospace'; el.style.whiteSpace = 'pre-wrap';
    el.textContent = 'FATAL ERROR: ' + (e.error && e.error.stack ? e.error.stack : (e.message || String(e)));
    document.body.appendChild(el);
  } catch (err) { console.error('Error showing overlay', err); }
});
window.addEventListener('unhandledrejection', function (ev) {
  console.error('Unhandled promise rejection', ev.reason);
  try {
    const el = document.getElementById('fatal-error-overlay') || document.createElement('div');
    el.id = 'fatal-error-overlay';
    el.style.position = 'fixed'; el.style.left = '8px'; el.style.top = '8px'; el.style.right = '8px';
    el.style.padding = '10px'; el.style.background = 'rgba(40,0,0,0.9)'; el.style.color = '#fff'; el.style.zIndex = 9999;
    el.style.fontFamily = 'monospace'; el.style.whiteSpace = 'pre-wrap';
    el.textContent = 'UNHANDLED REJECTION: ' + (ev.reason && ev.reason.stack ? ev.reason.stack : String(ev.reason));
    document.body.appendChild(el);
  } catch (err) { console.error('Error showing overlay', err); }
});

