function getEpochContentProfile(epochId) {
  return EPOCH_CONTENT_PROFILES[epochId] || EPOCH_CONTENT_PROFILES.mesopotamia;
}

function getEpochUiProfile(epochId) {
  return EPOCH_UI_PROFILES[epochId] || EPOCH_UI_PROFILES.mesopotamia;
}

function getEpochText(key, fallback = '') {
  const ui = getEpochUiProfile(window._currentEpoch || 'mesopotamia');
  return (ui && ui.texts && ui.texts[key]) || fallback;
}

function getResourceDisplay(resourceId) {
  const ui = getEpochUiProfile(window._currentEpoch || 'mesopotamia');
  const meta = ui && ui.resources ? ui.resources[resourceId] : null;
  if (meta) return meta;
  if (resourceId === 'seed') return { label: 'Semillas', productionLabel: 'semillas' };
  if (resourceId === 'wheat') return { label: 'Trigo', productionLabel: 'trigo' };
  if (resourceId === 'brick') return { label: 'Ladrillos', productionLabel: 'ladrillos' };
  if (resourceId === 'pop') return { label: 'Población', productionLabel: 'población' };
  return { label: resourceId, productionLabel: resourceId };
}

function isGroundPickupResourceSubtype(subtype) {
  const t = String(subtype || '').toLowerCase();
  return t !== 'mountain' && t !== 'campfire' && t !== 'furnace';
}

function getBuildingDisplay(type) {
  const resolved = resolveEpochBuildingType(type);
  const base = getBuildingDef(resolved) || getBuildingDef(type) || { name: type || 'Edificio', desc: '' };
  const ui = getEpochUiProfile(window._currentEpoch || 'mesopotamia');
  const override = (ui && ui.buildings && (ui.buildings[resolved] || ui.buildings[type])) || null;
  return override ? { ...base, ...override } : base;
}

function getEpochBuildPalette(epochId) {
  const key = epochId || window._currentEpoch || 'mesopotamia';
  if (key === 'urss') {
    return ['soviet_block', 'party_hq', 'collective_farm', 'factory', 'state_warehouse', 'soviet_superblock', 'soviet_superblock_b', 'steel_foundry', 'well', 'lamp_post', 'soviet_streetlight', 'soviet_monument', 'sheepfold'];
  }
  // El observatorio va al FINAL a propósito: los ocho primeros puestos están
  // casados uno a uno con los botones de construir y con los atajos H/V/F/Y/K/G/Z.
  // Su botón se marca con `data-fijo` (ver remapBuildButtonsForEpoch).
  return ['house', 'mesopotamian_villa_detailed', 'farm', 'temple', 'market', 'granary', 'ziggurat', 'road', 'well', 'fountain', 'lamp_post', 'reed_hut', 'pottery', 'sheepfold', 'dock', 'watchtower', 'observatory'];
}

function remapBuildButtonsForEpoch() {
  try {
    const palette = getEpochBuildPalette(window._currentEpoch || 'mesopotamia');
    const buttons = Array.from(document.querySelectorAll('.build-btn'));
    for (let i = 0; i < buttons.length; i++) {
      const btn = buttons[i];
      // Los botones marcados con `data-fijo` NO se remapean por posición: no todos
      // los edificios existen en todas las épocas. El observatorio es mesopotámico
      // (en la URSS las tablillas están en un museo), así que se oculta cuando la
      // paleta no lo incluye en vez de convertirse en otro edificio por el índice.
      const fijo = btn.dataset ? btn.dataset.fijo : null;
      if (fijo) {
        const disponible = palette.indexOf(fijo) >= 0;
        btn.style.display = disponible ? '' : 'none';
        if (!disponible && selectedTool === fijo) {
          selectedTool = null;
          try { btn.classList.remove('selected'); } catch (e) {}
        }
        continue;
      }
      const mappedType = palette[i] || btn.dataset.type;
      btn.dataset.type = mappedType;
    }
  } catch (e) {}
}

function getEpochKeyBuildMap() {
  const palette = getEpochBuildPalette(window._currentEpoch || 'mesopotamia');
  return {
    h: palette[0] || 'house',
    v: palette[1] || 'mesopotamian_villa_detailed',
    f: palette[2] || 'farm',
    y: palette[3] || 'temple',   // T está reservada para la cámara (libre/seguimiento)
    k: palette[4] || 'market',
    g: palette[5] || 'granary',
    z: palette[6] || 'ziggurat',
    d: 'demolish',
    Escape: null
  };
}

function getEpochShortcutSummary() {
  const palette = getEpochBuildPalette(window._currentEpoch || 'mesopotamia');
  return 'Atajos: '
    + `H=${getBuildingDisplay(palette[0] || 'house').name} `
    + `V=${getBuildingDisplay(palette[1] || 'mesopotamian_villa_detailed').name} `
    + `F=${getBuildingDisplay(palette[2] || 'farm').name} `
    + `Y=${getBuildingDisplay(palette[3] || 'temple').name} `
    + `K=${getBuildingDisplay(palette[4] || 'market').name} `
    + `G=${getBuildingDisplay(palette[5] || 'granary').name} `
    + `Z=${getBuildingDisplay(palette[6] || 'ziggurat').name} `
    + `D=${getEpochText('demolishName', 'Demoler')}`
    + ` · T=${getEpochText('cameraFollow', 'Cámara libre/seguimiento')}`;
}

function updateStaticEpochUI() {
  try {
    const wheat = getResourceDisplay('wheat');
    const brick = getResourceDisplay('brick');
    const pop = getResourceDisplay('pop');
    const setText = (id, text) => {
      const el = document.getElementById(id);
      if (el) el.textContent = text;
    };

    setText('label-res-wheat', `${wheat.label}:`);
    setText('label-res-brick', `${brick.label}:`);
    setText('label-res-pop', `${pop.label}:`);
    setText('panel-title-build', getEpochText('buildPanelTitle', 'Construir'));
    setText('panel-title-production', getEpochText('productionPanelTitle', 'Producción / Turno'));
    setText('prod-label-wheat', wheat.productionLabel || wheat.label.toLowerCase());
    setText('prod-label-brick', brick.productionLabel || brick.label.toLowerCase());
    setText('prod-label-pop', pop.productionLabel || pop.label.toLowerCase());
    setText('btn-demolish-name', getEpochText('demolishName', 'Demoler'));
    setText('btn-demolish-desc', getEpochText('demolishDesc', 'Recupera 50%'));

    remapBuildButtonsForEpoch();

    const quickTips = document.getElementById('main-menu-quicktips');
    if (quickTips) {
      const tips = getEpochUiProfile(window._currentEpoch || 'mesopotamia').quickTips || [];
      quickTips.innerHTML = `<b>${getEpochText('quickTipsTitle', 'Consejos')}</b><ul style="margin:6px 0 0 14px;padding:0;color:#bbb">${tips.map(t => `<li>${t}</li>`).join('')}</ul>`;
    }

    try { refreshBuildButtonsFromDefinitions(); } catch (e) {}
  } catch (e) {}
}

window._currentEpoch = window._currentEpoch || localStorage.getItem(STORAGE_EPOCH_KEY) || 'mesopotamia';

function getEpochProfile(epochId) {
  return EPOCH_PROFILES[epochId] || EPOCH_PROFILES.mesopotamia;
}

function applyEpochProfile(epochId, persist = true) {
  try {
    const key = EPOCH_PROFILES[epochId] ? epochId : 'mesopotamia';
    window._currentEpoch = key;
    if (persist) {
      try { localStorage.setItem(STORAGE_EPOCH_KEY, key); } catch (e) {}
    }
    const profile = getEpochProfile(key);
    try {
      if (document && document.body && document.body.classList) {
        document.body.classList.toggle('theme-urss', key === 'urss');
      }
    } catch (e) {}
    try { document.title = profile.gameTitle || 'MesoBuilder'; } catch (e) {}
    try {
      const h1 = document.querySelector('#topbar h1');
      if (h1) h1.innerHTML = `&#x2605; ${profile.gameTitle || 'MesoBuilder'} &#x2605;`;
    } catch (e) {}
    try { applyEpochContentProfile(key); } catch (e) {}
    try { updateStaticEpochUI(); } catch (e) {}
    return profile;
  } catch (e) {
    return getEpochProfile('mesopotamia');
  }
}

function unwrapSavedAppState(data) {
  try {
    if (!data || typeof data !== 'object') return null;
    if (data.appState && typeof data.appState === 'object') return { ...data, ...data.appState };
    return data;
  } catch (e) {
    return null;
  }
}

// Debounced save helper
let _saveTimer = null;
function saveAppStateDebounced(delay = 1200) {
  if (_saveTimer) clearTimeout(_saveTimer);
  const busyCamera = isPanning || isZooming || zoomAnimating || (Date.now() - lastCameraInputAt) < 350;
  const finalDelay = busyCamera ? Math.max(delay, 2200) : Math.max(700, delay);
  _saveTimer = setTimeout(() => { try { saveAppState(); } catch (e) {} }, finalDelay);
}

// Copia superficial de una entidad descartando los campos transitorios del modo
// debug (rectángulo dibujado) para no ensuciar el guardado.
function stripTransientDebugFields(ent) {
  try {
    if (!ent || typeof ent !== 'object') return ent;
    const copy = { ...ent };
    delete copy._dbgRect;
    delete copy._dbgRectAt;
    return copy;
  } catch (e) { return ent; }
}

// ¿El mundo actual tiene CONTENIDO de verdad?
// Sirve para dos cosas: no guardar un mundo vacío y detectar un guardado roto.
// OJO: NO se exige `_TERRAIN_SEED`. Las partidas guardadas antiguas (anteriores a
// que existiera la semilla de terreno) tienen mundo de sobra pero sin semilla, y
// con la comprobación estricta se DESCARTABAN: se regeneraba el mundo y el
// jugador veía «otro terreno» (o ninguno). Ahora basta con biomas variados o con
// un mundo poblado.
function mundoTieneContenido() {
  try {
    if (!Array.isArray(tileBiome) || !tileBiome.length) return false;
    const set = new Set();
    for (let r = 0; r < ROWS; r += 7) {
      const row = tileBiome[r];
      if (!row) continue;
      for (let c = 0; c < COLS; c += 7) set.add(row[c]);
      if (set.size > 2) return true;
    }
    if (set.size > 2) return true;
    const ent = (typeof entities !== 'undefined' && entities) ? entities.length : 0;
    return ent > 25;
  } catch (e) { return false; }
}

// Deja SIEMPRE un mundo jugable: carga el guardado y, si no hay o viene vacío
// (arena del arranque sin mundo), genera uno nuevo. Antes, un guardado que se
// había escrito sin mundo dejaba el juego «sin renderizar el terreno» para
// siempre, porque se volvía a cargar tal cual.
function asegurarMundoCargado() {
  let restaurado = false;
  try { restaurado = !!loadAppState(); } catch (e) { restaurado = false; }
  if (restaurado && mundoTieneContenido()) return true;
  try { console.warn('boot: el guardado no trae mundo jugable (' + (restaurado ? 'vacio' : 'no se pudo leer') + '), se genera uno nuevo'); } catch (e) {}
  try {
    window._TERRAIN_SEED = null;
    window._homePrologue = null;
    generateMap('random', { freshSeed: true });
  } catch (e) { console.error('boot: fallo generando el mundo de reemplazo', e); }
  return mundoTieneContenido();
}

function saveAppState() {
  try {
    // Nunca se guarda un mundo REALMENTE vacío (el arranque sin mundo deja una
    // rejilla de arena con un par de entidades): así el autoguardado no pisa la
    // partida buena. El criterio es estrecho A PROPÓSITO: cualquier mundo con
    // biomas variados o con un mínimo de contenido se guarda siempre.
    if (!Array.isArray(tileBiome) || !tileBiome.length) { console.warn('save: sin rejilla de terreno, se omite'); return false; }
    const biomas = new Set();
    for (let r = 0; r < ROWS; r += 9) {
      const row = tileBiome[r];
      if (!row) continue;
      for (let c = 0; c < COLS; c += 9) biomas.add(row[c]);
    }
    const nEnt = (typeof entities !== 'undefined' && entities) ? entities.length : 0;
    if (biomas.size <= 2 && nEnt < 12) { console.warn('save: mundo vacío (biomas=' + biomas.size + ', entidades=' + nEnt + '), se omite'); return false; }
    const panels = {};
    Object.keys(window.FLOATING_PANELS || {}).forEach(id => {
      try {
        const p = window.FLOATING_PANELS[id];
        const body = p.querySelector && p.querySelector('.floating-body');
        panels[id] = {
          left: p.style.left || null,
          top: p.style.top || null,
          right: p.style.right || null,
          bottom: p.style.bottom || null,
          width: p.style.width || null,
          height: p.style.height || null,
          transform: p.style.transform || null,
          display: (p.style.display === 'none') ? 'none' : 'block',
          minimized: body ? (body.style.display === 'none') : false,
          dragMoved: p.dataset && p.dataset.dragMoved === '1'
        };
      } catch (e) {}
    });
    // Save minimal grid and biomes (sparse) to reduce size: store full arrays for simplicity
    const state = {
      panels,
      player: { x: player.x, y: player.y, col: player.col, row: player.row, name: player.name, palette: player.palette, outfit: player.outfit, presetId: player.presetId, equipped: player.equipped || null },
      char: (typeof char !== 'undefined') ? char : null,
      res: (typeof res !== 'undefined') ? res : null,
      inventory: (inventory && typeof inventory === 'object') ? { ...inventory } : {},
      // Los CULTIVOS viajan con la partida: antes no se guardaban y al cargar el
      // campo aparecía vacío (eso es «no se guardan las partidas»).
      crops: (function () {
        try {
          const out = [];
          _crops.forEach((v, k) => out.push([k, v.stage | 0, Math.round(v.sec || 0), v.type || 'wheat', v.moist ? 1 : 0]));
          return out;
        } catch (e) { return []; }
      })(),
      // keep turn and flags
      turn: typeof turn === 'number' ? turn : 0,
      epoch: window._currentEpoch || 'mesopotamia',
      startLocked: !!startLocked,
      editMode: !!editMode,
      mapEditor: { enabled: !!mapEditorEnabled, brush: mapEditorBrush, brushSize: mapEditorBrushSize },
      camera: { camX: camX, camY: camY, zoom: zoom },
      selectedTool: selectedTool,
      tileBiome,
      grid,
      // Semilla y ríos del generador coherente: sin esto, el mundo que crezca tras
      // cargar la partida no continuaría el mismo terreno.
      terrain: { seed: window._TERRAIN_SEED || null, rivers: window._RIVERS || null },
      bridges: serializeBridgeMap(),
      entities: (window._savedExterior && Array.isArray(window._savedExterior.entities))
        ? window._savedExterior.entities.map(e => stripTransientDebugFields(e))
        : (Array.isArray(entities) ? entities.map(e => stripTransientDebugFields(e)).filter(e => e && e.kind !== 'preview') : []),
      rabbits: (window._savedExterior && Array.isArray(window._savedExterior.rabbits))
        ? window._savedExterior.rabbits.map(r => ({ ...r }))
        : (Array.isArray(rabbits) ? rabbits.map(r => ({ ...r })) : []),
      foxes: (window._savedExterior && Array.isArray(window._savedExterior.foxes))
        ? window._savedExterior.foxes.map(f => ({ ...f }))
        : (Array.isArray(foxes) ? foxes.map(f => ({ ...f })) : []),
      graves: (Array.isArray(graves) ? graves.map(g => ({ ...g })) : []),
      enemies: (typeof enemies !== 'undefined' && Array.isArray(enemies)) ? enemies.map(en => ({ ...en })) : [],
      effectParticles: (typeof effectParticles !== 'undefined' && Array.isArray(effectParticles)) ? effectParticles.map(p => ({ ...p })) : [],
      floatingTexts: (typeof window.floatingTexts !== 'undefined' && Array.isArray(window.floatingTexts)) ? window.floatingTexts.map(t => ({ ...t })) : [],
      villages: (window._VILLAGES && Array.isArray(window._VILLAGES)) ? window._VILLAGES.map(v => ({ ...v })) : [],
      structures: (() => { try { return structureSystem.listPlaced(); } catch (e) { return []; } })(),
      interiorDoors: (window.INTERIOR_DOORS && Array.isArray(window.INTERIOR_DOORS)) ? window.INTERIOR_DOORS.map(d => ({ ...d })) : [],
      storyChapter: window._storyChapter || 0,
      storySceneFlags: { ...(window._storySceneFlags || {}) }
    };
    // Las partículas y los textos flotantes son efímeros: no se guardan (además
    // engordaban el guardado sin servir para nada al volver a entrar).
    delete state.effectParticles;
    delete state.floatingTexts;
    const json = JSON.stringify(state);
    try {
      localStorage.setItem(APP_STATE_KEY, json);
    } catch (errQuota) {
      // Cuota llena (localStorage ronda los 5 MB): se libera lo prescindible y se
      // reintenta UNA vez. Antes este fallo se tragaba en silencio y el jugador
      // perdía la partida sin enterarse.
      console.warn('save: fallo al guardar', errQuota);
      try {
        delete state.villages; delete state.structures; delete state.crops;
        localStorage.setItem(APP_STATE_KEY, JSON.stringify(state));
        try { notify('Partida guardada sin detalles secundarios (poco espacio).'); } catch (e) {}
      } catch (err2) {
        console.error('save: no se pudo guardar la partida', err2);
        try { notify('¡No se pudo guardar la partida! Falta espacio en el navegador.'); } catch (e) {}
        try { if (typeof SoundManager !== 'undefined') SoundManager.playSFX('error'); } catch (e) {}
      }
    }
    try { sessionStorage.setItem('meso.panelsSession', JSON.stringify(panels)); } catch (e) { /* ignore */ }
    try { window._lastSaveBytes = json.length; window._lastSaveAt = Date.now(); } catch (e) {}
    return true;
  } catch (err) { console.warn('save: excepción al guardar', err); return false; }
}

function loadAppState() {
  try {
    const raw = localStorage.getItem(APP_STATE_KEY);
    if (!raw) return null;
    const s = unwrapSavedAppState(JSON.parse(raw));
    if (!s) return null;
    // El mundo pudo CRECER: la partida guardada trae rejillas más grandes. Se
    // adoptan sus dimensiones (y su semilla de terreno) antes de copiar nada.
    try {
      const sRows = Array.isArray(s.tileBiome) ? s.tileBiome.length : 0;
      const sCols = (sRows && Array.isArray(s.tileBiome[0])) ? s.tileBiome[0].length : 0;
      if (sRows > 0 && sCols > 0) resizeWorldTo(sCols, sRows);
      if (s.terrain && typeof s.terrain === 'object') {
        if (typeof s.terrain.seed === 'number') window._TERRAIN_SEED = s.terrain.seed | 0;
        if (Array.isArray(s.terrain.rivers) && s.terrain.rivers.length) window._RIVERS = s.terrain.rivers.map(r => ({ base: Number(r && r.base) || 0 }));
      }
      // Partidas antiguas: no guardaban `terrain.seed`. Sin semilla, el mundo no
      // puede crecer por los bordes ni elegir familia de cultivo de forma estable,
      // y (antes) el guardado se consideraba vacío y se DESCARTABA. Se deriva una
      // semilla estable del propio mundo guardado.
      if (typeof window._TERRAIN_SEED !== 'number') {
        let h = 0x5f356495;
        try {
          for (let r = 0; r < ROWS; r += 17) {
            const row = s.tileBiome && s.tileBiome[r];
            if (!row) continue;
            for (let c = 0; c < COLS; c += 17) {
              const b = row[c];
              if (typeof b === 'string') { for (let i = 0; i < b.length; i++) h = Math.imul(h ^ b.charCodeAt(i), 16777619); }
            }
          }
        } catch (e) {}
        window._TERRAIN_SEED = (h | 0) || 1;
        try { console.warn('load: guardado sin semilla de terreno; se deriva', window._TERRAIN_SEED); } catch (e) {}
      }
    } catch (e) { console.warn('mundo: no se pudo adoptar el tamaño guardado', e); }
    try {
      if (s.tileBiome && Array.isArray(s.tileBiome)) {
        const copyRows = Math.min(ROWS, s.tileBiome.length);
        for (let r = 0; r < copyRows; r++) {
          const row = Array.isArray(s.tileBiome[r]) ? s.tileBiome[r].slice(0, COLS) : Array(COLS).fill('sand');
          while (row.length < COLS) row.push('sand');
          tileBiome[r] = row;
        }
        for (let r = copyRows; r < ROWS; r++) tileBiome[r] = Array(COLS).fill('sand');
      }
      // El agua dibujada y la comprobada con isRiver deben coincidir: la partida
      // guardada trae los biomas pero no el mapa de meandros.
      rebuildRiverMapFromBiomes();
      // Los corredores logísticos tampoco viajan: se deducen del bioma.
      try { rebuildCanalMapFromBiomes(); } catch (e) {}
      // Los puentes sí viajan con la partida (sus celdas son calzada, no agua).
      try { restoreBridgeMap(s.bridges); } catch (e) {}
    } catch (e) { console.warn('tileBiome restore skipped due to malformed data', e); }
    try {
      if (s.grid && Array.isArray(s.grid)) {
        const copyRows = Math.min(ROWS, s.grid.length);
        for (let r = 0; r < copyRows; r++) {
          const row = Array.isArray(s.grid[r]) ? s.grid[r].slice(0, COLS) : Array(COLS).fill(null);
          while (row.length < COLS) row.push(null);
          grid[r] = row;
        }
        for (let r = copyRows; r < ROWS; r++) grid[r] = Array(COLS).fill(null);
        normalizeRestoredGrid();
        try { growLegacyZiggurats(); } catch (e) {}
      }
    } catch (e) { console.warn('grid restore skipped due to malformed data', e); }
    if (s.player && typeof s.player.x === 'number') {
      player.x = s.player.x; player.y = s.player.y; player.col = Math.floor(s.player.x); player.row = Math.floor(s.player.y);
      try { if (s.player.name) player.name = s.player.name; } catch (e) {}
      try { if (s.player.palette) player.palette = s.player.palette; } catch (e) {}
      try { if (s.player.outfit) player.outfit = s.player.outfit; } catch (e) {}
      try { if (s.player.presetId) player.presetId = s.player.presetId; } catch (e) {}
      try { player.equipped = s.player.equipped || null; } catch (e) {}
    }
    try {
      if (s.inventory && typeof s.inventory === 'object') {
        inventory = { ...s.inventory };
      }
    } catch (e) { console.warn('inventory restore skipped', e); }
    // Cultivos: se restauran con su fase, su reloj y su familia de planta.
    try {
      _crops.clear();
      if (Array.isArray(s.crops)) {
        s.crops.forEach(row => {
          if (!Array.isArray(row) || !row[0]) return;
          const [key, stage, sec, type, moist] = row;
          _crops.set(String(key), {
            stage: Math.max(0, Math.min(3, Number(stage) || 0)),
            sec: Number(sec) || 0,
            type: (typeof type === 'string' && (CROP_TYPES || []).indexOf(type) >= 0) ? type : 'wheat',
            moist: moist ? 1 : 0,
            nextAt: (typeof dayCount === 'number' ? dayCount : 0) + WHEAT_DAYS_PER_STAGE
          });
        });
      }
    } catch (e) { console.warn('crops restore skipped', e); }
    try {
      if (s.entities && Array.isArray(s.entities)) {
        entities.length = 0;
        s.entities.forEach(e => {
          if (!e || typeof e !== 'object') return;
          const it = { ...e };
          if (typeof it.col !== 'number') {
            if (typeof it.x === 'number') it.col = Math.floor(it.x);
            else it.col = 0;
          }
          if (typeof it.row !== 'number') {
            if (typeof it.y === 'number') it.row = Math.floor(it.y);
            else it.row = 0;
          }
          it.x = typeof it.x === 'number' ? it.x : it.col;
          it.y = typeof it.y === 'number' ? it.y : it.row;
          entities.push(it);
        });
      }
      if (s.rabbits && Array.isArray(s.rabbits)) {
        rabbits.length = 0;
        s.rabbits.forEach(r => {
          if (!r || typeof r !== 'object') return;
          const it = { ...r };
          if (typeof it.col !== 'number') {
            if (typeof it.x === 'number') it.col = Math.floor(it.x);
            else it.col = 0;
          }
          if (typeof it.row !== 'number') {
            if (typeof it.y === 'number') it.row = Math.floor(it.y);
            else it.row = 0;
          }
          it.x = typeof it.x === 'number' ? it.x : it.col;
          it.y = typeof it.y === 'number' ? it.y : it.row;
          rabbits.push(it);
        });
      }
      if (s.foxes && Array.isArray(s.foxes)) {
        foxes.length = 0;
        s.foxes.forEach(f => {
          if (!f || typeof f !== 'object') return;
          const it = { ...f };
          if (typeof it.col !== 'number') {
            if (typeof it.x === 'number') it.col = Math.floor(it.x);
            else it.col = 0;
          }
          if (typeof it.row !== 'number') {
            if (typeof it.y === 'number') it.row = Math.floor(it.y);
            else it.row = 0;
          }
          it.x = typeof it.x === 'number' ? it.x : it.col;
          it.y = typeof it.y === 'number' ? it.y : it.row;
          foxes.push(it);
        });
      }
      if (s.enemies && Array.isArray(s.enemies)) {
        try { enemies.length = 0; s.enemies.forEach(en => { if (!en || typeof en !== 'object') return; enemies.push({ ...en }); }); } catch (e) { console.warn('enemies restore error', e); }
      }
      if (s.graves && Array.isArray(s.graves)) {
        try { graves.length = 0; s.graves.forEach(g => { if (!g || typeof g !== 'object') return; graves.push({ ...g }); }); } catch (e) { console.warn('graves restore error', e); }
      }
      if (s.effectParticles && Array.isArray(s.effectParticles)) {
        try { effectParticles.length = 0; s.effectParticles.forEach(p => effectParticles.push({ ...p })); } catch (e) {}
      }
      if (s.floatingTexts && Array.isArray(s.floatingTexts)) {
        try { window.floatingTexts.length = 0; s.floatingTexts.forEach(t => window.floatingTexts.push({ ...t })); } catch (e) {}
      }
      if (s.villages && Array.isArray(s.villages)) {
        try { window._VILLAGES = s.villages.map(v => ({ ...v })); } catch (e) { window._VILLAGES = window._VILLAGES || []; }
      }
      if (s.structures && Array.isArray(s.structures)) {
        try { structureSystem.restorePlaced(s.structures); } catch (e) { console.warn('structures restore skipped', e); }
      }
      if (s.interiorDoors && Array.isArray(s.interiorDoors)) {
        try { window.INTERIOR_DOORS = s.interiorDoors.map(d => ({ ...d })); } catch (e) { window.INTERIOR_DOORS = window.INTERIOR_DOORS || []; }
      } else {
        try { rebuildInteriorDoorsFromGrid(); } catch (e) {}
      }
    } catch (e) { /* ignore restore errors */ }
    // Muralla × camino, con las entidades ya restauradas: abre los vanos que
    // falten (partidas viejas, hechas antes de esta pasada) y monta el control
    // de paso de las puertas que aún no lo tengan. Es idempotente.
    try { openWallGatesForRoads({ epoch: window._currentEpoch || 'mesopotamia' }); } catch (e) {}
    try {
      if (s.char && typeof s.char === 'object' && typeof char !== 'undefined') {
        Object.assign(char, s.char);
      }
    } catch (e) { console.warn('char restore skipped', e); }
    try {
      if (s.res && typeof s.res === 'object') {
        Object.keys(res || {}).forEach(key => {
          if (Object.prototype.hasOwnProperty.call(s.res, key)) res[key] = s.res[key];
        });
      }
    } catch (e) { console.warn('resource restore skipped', e); }
    try {
      if (s.epoch) applyEpochProfile(s.epoch, false);
    } catch (e) { console.warn('epoch restore skipped', e); }
    try {
      if (s.camera && typeof s.camera === 'object') {
        if (typeof s.camera.camX === 'number') camX = s.camera.camX;
        if (typeof s.camera.camY === 'number') camY = s.camera.camY;
        if (typeof s.camera.zoom === 'number') {
          zoom = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, s.camera.zoom));
          targetZoom = zoom;
        }
      }
    } catch (e) { console.warn('camera restore skipped', e); }
    try {
      if (s.mapEditor && typeof s.mapEditor === 'object') {
        mapEditorEnabled = !!s.mapEditor.enabled;
        if (typeof s.mapEditor.brush === 'string') mapEditorBrush = s.mapEditor.brush;
        if (typeof s.mapEditor.brushSize === 'number') mapEditorBrushSize = s.mapEditor.brushSize;
      }
    } catch (e) { console.warn('map editor restore skipped', e); }
    try {
      if (typeof s.selectedTool === 'string' || s.selectedTool === null) selectedTool = s.selectedTool || null;
    } catch (e) { console.warn('selected tool restore skipped', e); }
    try {
      if (typeof s.editMode === 'boolean') setEditMode(s.editMode);
    } catch (e) { console.warn('edit mode restore skipped', e); }
    try {
      const modal = document.getElementById('char-select');
      startLocked = !!s.startLocked && !!(modal && !modal.classList.contains('hidden'));
    } catch (e) {
      startLocked = false;
    }
    try { clampCamera(); } catch (e) {}
    try { updateUI(); } catch (e) {}
    try { updateInventory(); } catch (e) {}
    try { if (window.updateEquippedUI) window.updateEquippedUI(); } catch (e) {}
    try { updateCharCard(); } catch (e) {}
    window._MESO_SAVED_STATE = s;
    try { restoreRegisteredPanelsFromState(s.panels || {}); } catch (e) {}
    return s;
  } catch (err) {
    console.warn('loadAppState failed', err);
    return null;
  }
}

