const player = {
  col: 14,
  row: 12,
  name: 'Ur-Nammu',
  title: 'Rey de Sumer',
  kind: 'player',
  palette: DEFAULT_PALETTE,
  outfit: 'tunic',
  presetId: null
};
// El jugador debe estar accesible globalmente: otros módulos (spatial index,
// selección RTS, cinemáticas con el nombre del protagonista, debug HUD) leen
// `window.player`. Hasta ahora nunca se asignaba y esas rutas usaban (0,0).
try { window.player = player; } catch (e) {}
// El inventario también se lee desde fuera (HUD, misiones y pruebas de labrado).
// Se expone con un getter porque `inventory` se reasigna al cargar partida.
try {
  if (!Object.getOwnPropertyDescriptor(window, 'inventory')) {
    Object.defineProperty(window, 'inventory', { configurable: true, get: () => inventory });
  }
} catch (e) {}
// survival stats stored on char; ensure defaults
try {
  char.hunger = typeof char.hunger === 'number' ? char.hunger : 100;
  char.thirst = typeof char.thirst === 'number' ? char.thirst : 100;
  char.maxHunger = typeof char.maxHunger === 'number' ? char.maxHunger : 100;
  char.maxThirst = typeof char.maxThirst === 'number' ? char.maxThirst : 100;
  // decay rates per second
  window.SURVIVAL_HUNGER_RATE = window.SURVIVAL_HUNGER_RATE || 0.05; // hunger per second
  window.SURVIVAL_THIRST_RATE = window.SURVIVAL_THIRST_RATE || 0.08; // thirst per second
  char._lastSurvivalTick = char._lastSurvivalTick || Date.now();
} catch (e) {}
player.weapon = null; // equipped weapon id (optional)
player._makarovClip = 0;

// Initialize stamina
player.stamina = 100;
player._maxStamina = 100;
player._isSprinting = false;
player._jumpUntil = 0;

player.x = player.col;
player.y = player.row;
player.vx = 0;
player.vy = 0;
player.speed = 4.3 / TILE; // tiles por segundo al caminar (antes 6=TILE: iba demasiado rápido)
player._baseSpeed = player.speed;
// animation / facing defaults
player.dir = 'down';
player.equipped = null;
player._attackStartedAt = 0;
player._attackAnimUntil = 0;
player._attackHit = false;
player._walkTime = 0;
player._walkFrame = 0;
player._shakeUntil = 0;
player._shakeMag = 0;
// Caja del jugador en pantalla (la rellena drawPlayer cada fotograma). Sirve
// para colocar avisos encima del personaje sabiendo dónde está de verdad el
// sprite (antes la vida se colocaba desde la celda y se comía la etiqueta del
// nombre, que sale justo encima de la cabeza).
let _playerScreenBox = null;

window._wantedLevel = window._wantedLevel || 0;
window._wantedDecayAt = window._wantedDecayAt || 0;

function getPetDialogueLine(context, pet) {
  const dogName = (pet && pet.name) || DEFAULT_PET_DOG_NAME;
  const linesByContext = {
    pet: [
      `${dogName}, eres el mejor compañero.`,
      `Buen chico, ${dogName}. Quédate conmigo.`,
      `Tranquilo, ${dogName}. Todo está bien.`
    ],
    feed: [
      `Come, ${dogName}. Te lo has ganado.`,
      `${dogName}, hay comida para ti.`,
      `Despacio, ${dogName}. Hay de sobra.`
    ],
    call: [
      `${dogName}, ven aquí.`,
      `¡Conmigo, ${dogName}!`,
      `${dogName}, te necesito a mi lado.`
    ],
    alone: [
      `${dogName}, solo te tengo a ti en este lugar.`,
      `Qué silencio... menos mal que estás aquí, ${dogName}.`,
      `${dogName}, contigo no me siento solo.`
    ]
  };
  const lines = linesByContext[context] || linesByContext.alone;
  return lines[Math.floor(Math.random() * lines.length)] || `${dogName}, vamos.`;
}

function speakToPet(context, pet, opts = {}) {
  try {
    const line = getPetDialogueLine(context, pet);
    if (!line) return;
    notify(line);
    if (opts.forceBubble && window.spawnFloatingText && pet) {
      window.spawnFloatingText((pet.x || pet.col) + 0.2, (pet.y || pet.row) - 0.3, '🐾', { color: '#FFD27A', force: true });
    }
  } catch (e) {}
}

function callPetDogToPlayer() {
  try {
    const pet = getActivePetDog();
    if (!pet) {
      notify('No tienes perro compañero activo.');
      return false;
    }
    pet.behavior = 'follow';
    const distToPlayer = Math.hypot((player.x + 0.5) - (pet.x || pet.col), (player.y + 0.5) - (pet.y || pet.row));
    const safe = findNearestWalkable(Math.floor(player.x + 1), Math.floor(player.y + 1), 5);
    pet.moveTarget = { x: safe.col + 0.5, y: safe.row + 0.5 };
    pet._baseSpeed = typeof pet._baseSpeed === 'number' ? pet._baseSpeed : (pet.speed || 1.8);
    pet.speed = Math.max(pet._baseSpeed, distToPlayer > 8 ? 3.3 : 2.6);
    pet._recallSprintUntil = Date.now() + (distToPlayer > 8 ? 5200 : 2600);
    pet._petJumpUntil = Date.now() + 420;
    pet._lastInteractionAt = Date.now();
    speakToPet('call', pet, { forceBubble: true });
    return true;
  } catch (e) {
    return false;
  }
}

function getActivePetDog() {
  try {
    return entities.find(ent => ent && ent.kind === 'pet' && ent.petType === 'dog') || null;
  } catch (e) {
    return null;
  }
}

function ensurePetDogCompanion(opts = {}) {
  try {
    const existing = getActivePetDog();
    if (existing && !opts.force) return existing;
    const name = DEFAULT_PET_DOG_NAME;
    if (existing) {
      existing.name = name;
      if (!existing.behavior) existing.behavior = 'follow';
      if (typeof existing.x !== 'number') existing.x = (typeof existing.col === 'number') ? existing.col : player.x;
      if (typeof existing.y !== 'number') existing.y = (typeof existing.row === 'number') ? existing.row : player.y;
      return existing;
    }
    const c = Math.max(0, Math.min(COLS - 1, Math.floor((player.col || 0) + 1)));
    const r = Math.max(0, Math.min(ROWS - 1, Math.floor((player.row || 0) + 1)));
    const safe = canWalkTo(c, r) ? { col: c, row: r } : findNearestWalkable(c, r, 6);
    const dog = {
      id: 'pet-dog-main',
      kind: 'pet',
      petType: 'dog',
      name,
      col: safe.col,
      row: safe.row,
      x: safe.col + 0.5,
      y: safe.row + 0.5,
      hp: 24,
      maxHp: 24,
      speed: 1.8,
      size: 0.7,
      behavior: 'follow',
      combatMode: false,
      loyalty: 60,
      hunger: 80,
      maxHunger: 100,
      energy: 90,
      maxEnergy: 100,
      playType: 'fetch',
      _lastInteractionAt: 0
    };
    entities.push(dog);
    return dog;
  } catch (e) {
    return null;
  }
}

function interactWithPetDog(action, dog) {
  try {
    const pet = dog || getActivePetDog();
    if (!pet) return;
    if (action === 'toggle-follow') {
      pet.behavior = pet.behavior === 'stay' ? 'follow' : 'stay';
      if (pet.behavior === 'stay' && pet.moveTarget) delete pet.moveTarget;
      notify(pet.behavior === 'stay' ? `${pet.name} se queda aquí.` : `${pet.name} te sigue.`);
      return;
    }
    if (action === 'toggle-attack') {
      pet.combatMode = !pet.combatMode;
      if (pet.combatMode) {
        pet.behavior = 'follow';
        notify(`${pet.name} protegerá y atacará enemigos cercanos.`);
      } else {
        notify(`${pet.name} deja el modo ataque.`);
      }
      return;
    }
    if (action === 'pet') {
      pet._lastInteractionAt = Date.now();
      pet.loyalty = Math.min(100, (pet.loyalty || 60) + 6);
      pet._petJumpUntil = Date.now() + 520;
      // Reaccion visible: trote rapido, saltito y corazones durante ~2 s.
      pet._petUntil = Date.now() + 2000;
      pet._heartAt = 0;
      try { sfx('dogHappy'); } catch (e) {}
      try { setTimeout(() => { try { sfx('dogBark3', { volume: 0.7 }); } catch (e) {} }, 380); } catch (e) {}
      try { if (window.spawnFloatingText) window.spawnFloatingText((pet.x || pet.col) + 0.2, (pet.y || pet.row) - 0.1, '❤', { color: '#FFD27A', force: true }); } catch (e) {}
      notify(`Acaricias a ${pet.name}.`);
      speakToPet('pet', pet);
      return;
    }
    if (action === 'feed') {
      const foodKey = (inventory && inventory.food > 0) ? 'food' : ((inventory && inventory.wheat > 0) ? 'wheat' : null);
      if (!foodKey) {
        notify(`No tienes comida para ${pet.name}.`);
        return;
      }
      inventory[foodKey] = Math.max(0, (inventory[foodKey] || 0) - 1);
      if (inventory[foodKey] <= 0) delete inventory[foodKey];
      pet.hp = Math.min(pet.maxHp || 24, (pet.hp || 0) + 5);
      pet.hunger = Math.min(pet.maxHunger || 100, (pet.hunger || 0) + 28);
      pet.energy = Math.min(pet.maxEnergy || 100, (pet.energy || 0) + 12);
      pet.loyalty = Math.min(100, (pet.loyalty || 60) + 10);
      pet._lastInteractionAt = Date.now();
      notify(`${pet.name} come feliz.`);
      speakToPet('feed', pet);
      try { if (window.spawnFloatingText) window.spawnFloatingText((pet.x || pet.col) + 0.2, (pet.y || pet.row) - 0.1, '+5', { color: '#9BE26F', force: true }); } catch (e) {}
      try { updateInventory(); } catch (e) {}
      try { saveAppStateDebounced(); } catch (e) {}
    }
  } catch (e) {}
}

let petRadialMenuActive = false;
let petRadialMenuMode = 'main';
let petRadialPointer = { x: 0, y: 0 };
let petRadialSelection = -1;
let petRadialTimeScaleBackup = null;

function openPetRadialMenu() {
  petRadialMenuActive = true;
  petRadialMenuMode = 'main';
  petRadialSelection = -1;
  if (petRadialTimeScaleBackup === null) {
    petRadialTimeScaleBackup = window._timeScale || 1;
  }
  window._timeScale = 0.25;
}

function closePetRadialMenu() {
  petRadialMenuActive = false;
  petRadialMenuMode = 'main';
  petRadialSelection = -1;
  if (petRadialTimeScaleBackup !== null) {
    window._timeScale = petRadialTimeScaleBackup;
    petRadialTimeScaleBackup = null;
  }
}

function startDogPlayMode(playType) {
  try {
    const pet = getActivePetDog();
    if (!pet) return;
    const baseSpd = typeof pet._baseSpeed === 'number' ? pet._baseSpeed : (pet._baseSpeed = pet.speed || 1.8);
    pet.playMode = true;
    pet.playType = playType || 'fetch';
    pet.fetchMode = false;
    pet.fetchTarget = null;
    pet._playExploreTarget = null;
    pet._playExploreUntil = 0;
    pet.behavior = 'follow';
    pet.speed = Math.max(baseSpd, 1.8);
    const durations = { fetch: 16000, chase: 12000, explore: 14000 };
    pet.playTimeout = Date.now() + (durations[pet.playType] || 14000);
    if (pet.playType === 'fetch') notify(`Juego: traer. Haz clic donde quieres que busque ${pet.name || 'el perro'}.`);
    else if (pet.playType === 'chase') notify(`Juego: persecución. ${pet.name || 'El perro'} corre tras de ti.`);
    else if (pet.playType === 'explore') notify(`Juego: explorar. ${pet.name || 'El perro'} olfatea alrededor.`);
    else notify(`Juego iniciado con ${pet.name || 'el perro'}.`);
  } catch (e) {}
}

const PET_RADIAL_OPTIONS = [
  { id: 'call', label: 'Ven', run: () => callPetDogToPlayer() },
  { id: 'toggle-follow', label: 'Seguir/Quieto', run: () => interactWithPetDog('toggle-follow') },
  { id: 'toggle-attack', label: 'Ataque', run: () => interactWithPetDog('toggle-attack') },
  { id: 'pet', label: 'Acariciar', run: () => interactWithPetDog('pet') },
  { id: 'feed', label: 'Dar comida', run: () => interactWithPetDog('feed') },
  { id: 'play', label: 'Jugar', run: () => { petRadialMenuMode = 'play'; petRadialSelection = -1; } }
];

const PET_PLAY_OPTIONS = [
  { id: 'fetch', label: 'Traer', run: () => startDogPlayMode('fetch') },
  { id: 'chase', label: 'Perseguir', run: () => startDogPlayMode('chase') },
  { id: 'explore', label: 'Explorar', run: () => startDogPlayMode('explore') },
  { id: 'back', label: 'Volver', run: () => { petRadialMenuMode = 'main'; petRadialSelection = -1; } }
];

function getPetRadialCenterScreen() {
  try {
    const p = worldToScreen(player.x + 0.5, player.y + 0.5);
    return { x: p.x, y: p.y };
  } catch (e) {
    return { x: canvas.width * 0.5, y: canvas.height * 0.5 };
  }
}

function getPetRadialHoverIndex(pointerX, pointerY, centerX, centerY) {
  const dx = pointerX - centerX;
  const dy = pointerY - centerY;
  const dist = Math.hypot(dx, dy);
  const innerRadius = 28;
  const outerRadius = 118;
  if (dist < innerRadius || dist > outerRadius) return -1;
  const n = PET_RADIAL_OPTIONS.length;
  const angle = (Math.atan2(dy, dx) + Math.PI * 2) % (Math.PI * 2);
  return Math.floor((angle / (Math.PI * 2)) * n) % n;
}

function executePetRadialSelection() {
  try {
    if (!petRadialMenuActive) return;
    const pet = getActivePetDog();
    if (!pet) {
      notify('No tienes perro compañero activo.');
      return true;
    }
    const options = petRadialMenuMode === 'play' ? PET_PLAY_OPTIONS : PET_RADIAL_OPTIONS;
    const center = getPetRadialCenterScreen();
    const idx = getPetRadialHoverIndex(petRadialPointer.x, petRadialPointer.y, center.x, center.y);
    if (idx < 0 || idx >= options.length) return true;
    const option = options[idx];
    if (option && typeof option.run === 'function') option.run();
    return true;
  } catch (e) {}
  return true;
}

