// ---------------------- UI helpers & persistence ----------------------
// Create overlay controls (follow button, inventory panel, settings)
function createOverlayUI() {
  if (window._standaloneEditorMode) return;
  // Use the existing "Ir a jugador" button as the follow-toggle and add a zoom slider
  const centerBtn = document.getElementById('btn-center-player');
  if (centerBtn) {
    function updateCenterBtn() {
      centerBtn.textContent = followPlayer ? 'Ir a jugador — Seguir: ON (T)' : 'Ir a jugador (T = seguir)';
    }
    _updateFollowButtonUI = updateCenterBtn;
    updateCenterBtn();
    centerBtn.addEventListener('click', () => {
      if (!editMode) {
        centerCameraOnPlayer();
        toggleCameraFollow();
      } else {
        centerCameraOnPlayer();
      }
    });
  }

  // Zoom slider control (bottom-left)
  if (!document.getElementById('zoom-control')) {
    const zc = document.createElement('div');
    zc.id = 'zoom-control';
    zc.style.position = 'fixed'; zc.style.left = '12px'; zc.style.bottom = '12px'; zc.style.zIndex = 2000;
    zc.style.padding = '8px'; zc.style.background = 'rgba(0,0,0,0.6)'; zc.style.borderRadius = '6px'; zc.style.color = '#fff';
    zc.innerHTML = `<div style="font-weight:700;margin-bottom:6px">Zoom</div><input id="zoom-slider" type="range" min="${ZOOM_MIN}" max="${ZOOM_MAX}" step="0.01" value="${zoom}" style="width:160px">`;
    document.body.appendChild(zc);
    const slider = document.getElementById('zoom-slider');
    slider.addEventListener('input', () => {
      const z = parseFloat(slider.value);
      if (!isNaN(z)) {
        targetZoom = z;
        zoom = z;
        markCameraInput();
        clampCamera();
      }
    });
  }
  try { registerClosableUIElements(); } catch (e) {}

  // Create top menu bar for window/panel management and settings
  try { createMenuBar(); } catch (err) { /* ignore */ }

  // Inventory panel (hidden by default) - uses #inventory-list updated elsewhere
  if (!document.getElementById('inventory-panel')) {
    const p = document.createElement('div');
    p.id = 'inventory-panel';
    p.setAttribute('data-title', 'Inventario');
    p.style.position = 'fixed'; p.style.left = '50%'; p.style.top = '50%'; p.style.transform = 'translate(-50%, -50%)'; p.style.zIndex = 2000;
    p.style.display = 'none';
    stylePanel(p);
    p.style.width = '760px';
    p.style.maxWidth = '92vw';
    p.style.minWidth = '560px';
    p.style.maxHeight = '78vh';
    p.innerHTML = `
      <div id="inventory-panel-body" style="display:grid;grid-template-columns:minmax(0,1fr) 250px;gap:16px;max-height:70vh;overflow:hidden;">
        <div style="display:flex;flex-direction:column;min-height:0;">
          <div style="font-size:12px;color:#bbb;margin-bottom:8px;">Haz clic para usar o arrastra un ítem al equipo o al panel de crafteo.</div>
          <div id="inventory-panel-list" style="flex:1;overflow:auto;padding-right:6px;"></div>
        </div>
        <div style="display:flex;flex-direction:column;gap:12px;">
          <div id="inventory-equip-slot" style="min-height:164px;border:1px dashed rgba(255,210,122,0.4);border-radius:10px;padding:12px;background:rgba(255,255,255,0.03);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;">
            <div style="font-weight:700;color:var(--sand-mid);margin-bottom:8px;">Equipo</div>
            <div id="inventory-equip-icon" style="width:56px;height:56px;display:flex;align-items:center;justify-content:center;margin-bottom:8px;"></div>
            <div id="inventory-equip-label" style="font-size:13px;color:#fff;margin-bottom:6px;">Nada equipado</div>
            <div id="inventory-equip-hint" style="font-size:12px;color:#bbb;">Arrastra aquí un arma u objeto equipable</div>
          </div>
          <button id="inventory-open-crafting" style="padding:10px 12px;border-radius:8px;border:1px solid #333;background:#222;color:#FFD27A;">Abrir crafteo</button>
          <button id="inventory-unequip-btn" style="padding:10px 12px;border-radius:8px;border:1px solid #333;background:#341a1a;color:#FFD27A;">Desequipar</button>
          <div style="font-size:12px;color:#bbb;line-height:1.4;">Tip: arrastra un ítem directamente sobre una receta para craftear si tienes materiales.</div>
        </div>
      </div>`;
    document.body.appendChild(p);
    const openCraftBtn = document.getElementById('inventory-open-crafting');
    if (openCraftBtn) openCraftBtn.addEventListener('click', () => { try { toggleCraftingPanel(); } catch (e) {} });
    const unequipBtn = document.getElementById('inventory-unequip-btn');
    if (unequipBtn) unequipBtn.addEventListener('click', () => { try { window.unequipItem(); updateInventory(); } catch (e) {} });
  }

  // Entity info panel (right-click)
  if (!document.getElementById('entity-info')) {
    const info = document.createElement('div');
    info.id = 'entity-info';
    info.style.position = 'fixed'; info.style.left = '50%'; info.style.top = '50%'; info.style.transform = 'translate(-50%,-50%)';
    info.style.zIndex = 3000; info.style.display = 'none'; info.style.minWidth = '220px';
    stylePanel(info);
    info.innerHTML = `<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><strong id="entity-info-title">Entidad</strong></div><div id="entity-info-body"></div>`;
    document.body.appendChild(info);
  }

  // (settings gear removed — use top-menubar 'Ajustes' instead)
}

// Ability bar and missions UI
function ensureBottomHudDock() {
  if (window._standaloneEditorMode) return null;
  let dock = document.getElementById('bottom-hud-dock');
  if (!dock) {
    dock = document.createElement('div');
    dock.id = 'bottom-hud-dock';
    dock.style.position = 'fixed';
    dock.style.left = '50%';
    dock.style.bottom = '8px';
    dock.style.transform = 'translateX(-50%)';
    dock.style.display = 'flex';
    dock.style.alignItems = 'flex-end';
    dock.style.gap = '12px';
    dock.style.zIndex = '3900';
    dock.style.pointerEvents = 'none';
    document.body.appendChild(dock);
  }

  const bar = document.getElementById('ability-bar');
  const card = document.getElementById('char-card');
  if (card) {
    card.style.position = 'relative';
    card.style.left = 'auto';
    card.style.right = 'auto';
    card.style.top = 'auto';
    card.style.bottom = 'auto';
    card.style.transform = 'none';
    card.style.margin = '0';
    card.style.zIndex = '1';
    card.style.pointerEvents = 'auto';
    if (card.parentElement !== dock) dock.appendChild(card);
  }
  if (bar) {
    enforceAbilityBarHorizontal();
    bar.style.position = 'relative';
    bar.style.left = 'auto';
    bar.style.right = 'auto';
    bar.style.top = 'auto';
    bar.style.bottom = 'auto';
    bar.style.transform = 'none';
    bar.style.margin = '0';
    bar.style.zIndex = '1';
    bar.style.pointerEvents = 'auto';
    if (bar.parentElement !== dock) dock.appendChild(bar);
  }

  dock.style.display = ((card && card.style.display !== 'none' && !card.classList.contains('hidden')) || (bar && bar.style.display !== 'none')) ? 'flex' : 'none';
  return dock;
}

